import{_ as e,o,c as t,ae as r}from"./chunks/framework.Iv6F95cJ.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/arch-from-zero/旅程再启-架构师该如何适应新的技术浪潮？.md","filePath":"books/arch-from-zero/旅程再启-架构师该如何适应新的技术浪潮？.md"}'),a={name:"books/arch-from-zero/旅程再启-架构师该如何适应新的技术浪潮？.md"};function i(l,_,p,s,n,c){return o(),t("div",null,[..._[0]||(_[0]=[r("<p>你好，我是华仔！</p><p>不知不觉，从2018年专栏上线算起，到现在已经6年了，学习人数也突破了15万。</p><p>专栏完结后，我也经历了一些职业上的变动，先是去蚂蚁国际做了近2年的港澳钱包业务，然后离职做了《架构实战营》视频课，并且给很多行业龙头企业做咨询和培训，例如平安、华为、麦当劳、兴业银行、海信等。这些经历扩大了我的技术视野，通过接触不同行业不同业务不同团队，我得以从更多元更全面的角度去审视技术在不同业务和场景下的应用情况和效果。</p><p>除此以外，这6年时间也是技术热潮不断发展变化的6年：中台从火热到泛滥再到成为过街老鼠最后逐渐消失，云原生如火如荼的发展，大模型风靡全球成为新的技术风口……技术浪潮的涌动，也让我不断思考：<strong>这些技术对于架构师来说意味着什么，我们如何应对它们带来的挑战，架构师该如何进化适应新的浪潮？</strong></p><p>但无论风云如何变幻，我依然践行着自己最初的理念：帮助更多同学更快更好地掌握架构设计，成为更好的架构师。这一切的起点都是《从0开始学架构》专栏，所以我决定对专栏内容做一次更新迭代。首先我会基于新积累的经验和知识来完善、补充专栏；其次会增加新技术浪潮对架构设计带来的变化、挑战，分享架构师该如何进化来适应新的浪潮。</p><p><strong>总的来说，我会补充以下内容</strong>（实际交付篇幅和标题以正式上线内容为准）：</p><ul><li>微服务架构技巧：接口类设计技巧</li><li>微服务架构技巧：分布式事务</li><li>异地多活架构模式</li><li>云原生时代架构师的进化</li><li>大模型时代架构师的进化</li><li>架构演进的技巧与原则</li><li>架构师面试和晋升</li></ul><p>每周加更一篇，敬请期待！如果你有更多想要了解的内容，也欢迎在留言区告诉我！ 精选留言（7） Geek_e9e5f5 👍（4） 💬（1）华仔真的很用心，上了您的了受益匪浅2024-12-19vooc 👍（1） 💬（1）随着AI的高速发展，程序员应该何去何从，对于普通程序员来说计算机行业还有机会吗，或者对不同程序员群体有什么建议呢？2025-01-02Shawn 👍（0） 💬（1）期待老师讲讲微服务怎么拆？如何把控拆分粒度2025-01-17斯蒂芬.赵 👍（0） 💬（1）云原生这快主要讲啥2025-01-14MetaElection 👍（1） 💬（0）华仔确实用心了，期待这个专栏能够持续更新，能够给大家分享更多最新的技术，👍2025-01-03存活 👍（0） 💬（0）学习2025-01-14大布丁 👍（0） 💬（0）好啊，赶上热乎乎的饭菜了！2025-01-14</p>",8)])])}const d=e(a,[["render",i]]);export{m as __pageData,d as default};
